"use client";

import Link from "next/link";
import { useRef } from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { business } from "@/lib/business";
import { Arrow } from "@/components/Icons";
import { WatchButton } from "@/components/SiteChrome";
import { homeHeroContent } from "@/lib/companyContent";

gsap.registerPlugin(useGSAP);

export function HomeHero() {
  const root = useRef<HTMLElement>(null);

  useGSAP(
    () => {
      const el = root.current;
      if (!el) return;

      const media = el.querySelector<HTMLElement>(".home-hero-media");
      const video = el.querySelector<HTMLElement>(".home-hero-video");
      const veil = el.querySelector<HTMLElement>(".home-hero-veil");
      const brand = el.querySelector<HTMLElement>(".home-hero-brand");
      const words = gsap.utils.toArray<HTMLElement>(".split-word", el);
      const lede = el.querySelector<HTMLElement>(".home-hero-lede");
      const actions = gsap.utils.toArray<HTMLElement>(".home-hero-actions > *", el);
      const scroll = el.querySelector<HTMLElement>(".home-hero-scroll");
      const line = el.querySelector<HTMLElement>(".home-hero-rule");

      const textTargets = [brand, ...words, lede, ...actions, line, scroll].filter(
        Boolean
      ) as HTMLElement[];

      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
        gsap.set(textTargets, { clearProps: "all", autoAlpha: 1, y: 0, x: 0 });
        gsap.set([media, video, veil].filter(Boolean), { clearProps: "all", autoAlpha: 1, scale: 1 });
        el.classList.add("is-ready");
        return;
      }

      gsap.set(video, { scale: 1.14, autoAlpha: 0.55 });
      gsap.set(veil, { autoAlpha: 0 });
      gsap.set([brand, lede, line, scroll].filter(Boolean), { autoAlpha: 0, y: 28 });
      gsap.set(words, { autoAlpha: 0, y: 36 });
      gsap.set(actions, { autoAlpha: 0, y: 22 });

      const tl = gsap.timeline({
        defaults: { ease: "power3.out" },
        onComplete: () => el.classList.add("is-ready"),
      });

      tl.to(video, { scale: 1.04, autoAlpha: 1, duration: 1.55 }, 0)
        .to(veil, { autoAlpha: 1, duration: 1.1 }, 0.15);

      if (brand) tl.to(brand, { autoAlpha: 1, y: 0, duration: 0.75 }, 0.35);
      if (line) tl.to(line, { autoAlpha: 1, y: 0, duration: 0.65 }, 0.48);
      if (words.length) {
        tl.to(words, { autoAlpha: 1, y: 0, duration: 0.85, stagger: 0.048 }, 0.52);
      }
      if (lede) tl.to(lede, { autoAlpha: 1, y: 0, duration: 0.7 }, 0.95);
      if (actions.length) {
        tl.to(actions, { autoAlpha: 1, y: 0, duration: 0.65, stagger: 0.1 }, 1.08);
      }
      if (scroll) tl.to(scroll, { autoAlpha: 1, y: 0, duration: 0.6 }, 1.35);
    },
    { scope: root }
  );

  return (
    <section ref={root} className="home-hero" aria-label="Hind Landscape Co. introduction">
      <div className="home-hero-media" aria-hidden>
        {/* Poster for first paint / reduced-motion fallback */}
        <img
          className="home-hero-poster"
          src="/images/gallery-modern-lawn.png"
          alt=""
          width={1920}
          height={1080}
          fetchPriority="high"
        />
        <video
          className="home-hero-video"
          src={business.showreelVideo}
          poster="/images/gallery-modern-lawn.png"
          autoPlay
          muted
          loop
          playsInline
          preload="metadata"
        />
        <div className="home-hero-veil" />
        <div className="home-hero-grain" />
      </div>

      <div className="home-hero-frame">
        <div className="home-hero-copy">
          <p className="home-hero-brand">{homeHeroContent.brand}</p>
          <span className="home-hero-rule" aria-hidden />
          <h1 className="home-hero-title split-text is-manual">
            <span className="split-word">Transforming Spaces.</span>
            {"\u00A0"}
            <span className="split-word">Nurturing Nature.</span>
            <br />
            <span className="split-word">Creating Legacies.</span>
          </h1>
          <p className="home-hero-lede">{homeHeroContent.lede}</p>
          <div className="home-hero-actions">
            <Link href={homeHeroContent.primaryHref} className="btn btn-green home-hero-cta">
              {homeHeroContent.primaryCta} <Arrow />
            </Link>
            <Link href="/gallery" className="btn btn-outline home-hero-cta-secondary">
              {homeHeroContent.secondaryTitle}
            </Link>
            <WatchButton title="Watch our work" subtitle={homeHeroContent.secondarySubtitle} />
          </div>
        </div>
      </div>

      <div className="home-hero-scroll" aria-hidden>
        <span className="home-hero-scroll-label">Scroll</span>
        <span className="home-hero-scroll-line" />
      </div>
    </section>
  );
}

import { business } from "@/lib/business";
import { LEAD_SOURCE_LABELS, type LeadPayload } from "./types";

function esc(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function formatWhen(): string {
  return new Date().toLocaleString("en-IN", {
    timeZone: "Asia/Kolkata",
    dateStyle: "medium",
    timeStyle: "short",
  });
}

function detailLine(lead: LeadPayload): string {
  return lead.service || lead.propertyType || "General enquiry";
}

function buildFields(lead: LeadPayload): Array<[string, string | undefined]> {
  return [
    ["Form", LEAD_SOURCE_LABELS[lead.source]],
    ["Name", lead.name],
    ["Phone", lead.phone],
    ["Email", lead.email],
    ["Service", lead.service],
    ["Property type", lead.propertyType],
    ["Message", lead.message],
    ["Page", lead.pageUrl],
    ["Received (IST)", formatWhen()],
  ];
}

function fieldsToText(lead: LeadPayload): string {
  return buildFields(lead)
    .filter(([, value]) => value)
    .map(([label, value]) => `${label}: ${value}`)
    .join("\n");
}

function fieldsToHtml(lead: LeadPayload): string {
  return buildFields(lead)
    .filter(([, value]) => value)
    .map(
      ([label, value]) =>
        `<tr><td style="padding:8px 12px 8px 0;color:#555;font-size:14px;vertical-align:top;">${esc(label)}</td><td style="padding:8px 0;color:#111;font-size:14px;font-weight:600;vertical-align:top;">${esc(value!)}</td></tr>`
    )
    .join("");
}

/** Transactional layout — plain, inbox-friendly (not marketing-style). */
function transactionalShell(title: string, bodyText: string, bodyHtml: string): { html: string; text: string } {
  const text = `${title}\n\n${bodyText}\n\n—\n${business.name}\n${business.phone}\n${business.email}`;

  const html = `<!DOCTYPE html>
<html lang="en">
<head><meta charset="utf-8"></head>
<body style="margin:0;padding:24px;background:#ffffff;font-family:Arial,Helvetica,sans-serif;color:#111;">
  <p style="margin:0 0 16px;font-size:16px;font-weight:700;">${esc(title)}</p>
  <div style="font-size:14px;line-height:1.6;color:#222;">${bodyHtml}</div>
  <hr style="margin:24px 0;border:none;border-top:1px solid #e5e5e5;">
  <p style="margin:0;font-size:12px;line-height:1.5;color:#666;">
    ${esc(business.name)}<br>
    ${esc(business.phone)} · ${esc(business.email)}
  </p>
</body>
</html>`;

  return { html, text };
}

export function studioLeadEmail(lead: LeadPayload): { subject: string; html: string; text: string } {
  const detail = detailLine(lead);
  const fieldsText = fieldsToText(lead);

  const bodyText = `You have a new enquiry on ${business.siteUrl}.\n\n${fieldsText}\n\nCall the client: ${lead.phone}`;

  const bodyHtml = `
    <p style="margin:0 0 16px;">You have a new enquiry on your website.</p>
    <table role="presentation" cellspacing="0" cellpadding="0" style="border-collapse:collapse;">
      ${fieldsToHtml(lead)}
    </table>
    <p style="margin:16px 0 0;">
      Call client: <a href="tel:${esc(business.phoneTel)}" style="color:#1a5e37;">${esc(lead.phone)}</a>
    </p>`;

  const { html, text } = transactionalShell("New website enquiry", bodyText, bodyHtml);

  return {
    subject: `New enquiry: ${lead.name} · ${detail}`,
    html,
    text,
  };
}

export function clientConfirmationEmail(
  lead: LeadPayload
): { subject: string; html: string; text: string } | null {
  if (!lead.email) return null;

  const firstName = lead.name.trim().split(/\s+/)[0] || "there";
  const interest = detailLine(lead);

  const bodyText = `Hi ${firstName},

Thank you for choosing ${business.name}.

We have received your enquiry for ${interest}. Our landscape team will review your details and contact you on ${lead.phone} within a few working hours.

If you need anything urgent, call us on ${business.phone} or reply to this email.

Warm regards,
${business.name}
${business.tagline}`;

  const bodyHtml = `
    <p style="margin:0 0 12px;">Hi ${esc(firstName)},</p>
    <p style="margin:0 0 12px;">Thank you for choosing <strong>${esc(business.name)}</strong>.</p>
    <p style="margin:0 0 12px;">We have received your enquiry for <strong>${esc(interest)}</strong>. Our landscape team will review your details and contact you on <strong>${esc(lead.phone)}</strong> within a few working hours.</p>
    <p style="margin:0 0 12px;">If you need anything urgent, call us on <a href="tel:${esc(business.phoneTel)}" style="color:#1a5e37;font-weight:700;text-decoration:none;">${esc(business.phone)}</a> or reply to this email.</p>
    <p style="margin:0;">Warm regards,<br><strong>${esc(business.name)}</strong><br>${esc(business.tagline)}</p>`;

  const { html, text } = transactionalShell("Thank you for contacting us", bodyText, bodyHtml);

  return {
    subject: `Thank you for contacting ${business.name}`,
    html,
    text,
  };
}

"use client";

import { useState } from "react";
import { Arrow } from "@/components/Icons";
import {
  allowEmailKey,
  allowNameKey,
  allowPhoneKey,
  sanitizeEmail,
  sanitizeName,
  sanitizePhone,
  validateName,
  validateOptionalEmail,
  validatePhone,
  validateRequiredSelect,
} from "@/lib/formValidation";
import { submitLead } from "@/lib/leads/submitLead";

const propertyTypes = [
  "Home / Villa",
  "Farmhouse",
  "Restaurant / Café",
  "Hotel / Resort",
  "Corporate Campus",
  "Society / RWA",
  "Other",
];

export function LeadForm() {
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [property, setProperty] = useState("");
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [sent, setSent] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState("");
  const [honeypot, setHoneypot] = useState("");

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    if (honeypot) {
      setSent(true);
      return;
    }

    const errs: Record<string, string> = {};
    const nameErr = validateName(name);
    const phoneErr = validatePhone(phone);
    const emailErr = validateOptionalEmail(email);
    const propertyErr = validateRequiredSelect(property, "property type");
    if (nameErr) errs.name = nameErr;
    if (phoneErr) errs.phone = phoneErr;
    if (emailErr) errs.email = emailErr;
    if (propertyErr) errs.property = propertyErr;
    setErrors(errs);
    if (Object.keys(errs).length) return;

    setSubmitting(true);
    setSubmitError("");
    const result = await submitLead({
      source: "homepage-lead",
      name,
      phone,
      email: email.trim() || undefined,
      propertyType: property,
      honeypot,
    });
    setSubmitting(false);
    if (!result.ok) {
      setSubmitError(result.error);
      return;
    }
    setSent(true);
  }

  if (sent) {
    return (
      <div className="lead-success" role="status">
        <div className="lead-success-icon">✓</div>
        <h3>Request received!</h3>
        <p>
          We&apos;ll call <strong>{name}</strong> at <strong>{phone}</strong> within 4 hours
          to schedule a free site visit.
          {email.trim() ? " A confirmation email has been sent to you." : ""}
        </p>
      </div>
    );
  }

  return (
    <form className="lead-form" onSubmit={submit} noValidate>
      <label style={{ position: "absolute", left: -9999, width: 1, height: 1, overflow: "hidden" }} aria-hidden>
        <input type="text" name="url" tabIndex={-1} autoComplete="off" value={honeypot} onChange={(e) => setHoneypot(e.target.value)} />
      </label>

      <div className="lead-field">
        <input
          placeholder="Your name"
          value={name}
          maxLength={60}
          inputMode="text"
          autoComplete="name"
          onKeyDown={allowNameKey}
          onChange={(e) => {
            setName(sanitizeName(e.target.value));
            setErrors((p) => ({ ...p, name: "" }));
          }}
          className={errors.name ? "has-err" : ""}
        />
        {errors.name && <span className="lead-err">{errors.name}</span>}
      </div>

      <div className="lead-field">
        <input
          placeholder="Mobile number"
          type="tel"
          inputMode="numeric"
          pattern="[6-9][0-9]{9}"
          maxLength={10}
          value={phone}
          autoComplete="tel"
          onKeyDown={allowPhoneKey}
          onChange={(e) => {
            setPhone(sanitizePhone(e.target.value));
            setErrors((p) => ({ ...p, phone: "" }));
          }}
          className={errors.phone ? "has-err" : ""}
        />
        {errors.phone && <span className="lead-err">{errors.phone}</span>}
      </div>

      <div className="lead-field">
        <input
          placeholder="Email (optional)"
          type="email"
          inputMode="email"
          autoComplete="email"
          maxLength={80}
          value={email}
          onKeyDown={allowEmailKey}
          onChange={(e) => {
            setEmail(sanitizeEmail(e.target.value));
            setErrors((p) => ({ ...p, email: "" }));
          }}
          className={errors.email ? "has-err" : ""}
        />
        {errors.email && <span className="lead-err">{errors.email}</span>}
      </div>

      <div className="lead-field">
        <select
          value={property}
          onChange={(e) => {
            setProperty(e.target.value);
            setErrors((p) => ({ ...p, property: "" }));
          }}
          className={errors.property ? "has-err" : ""}
        >
          <option value="">Property type…</option>
          {propertyTypes.map((t) => (
            <option key={t} value={t}>
              {t}
            </option>
          ))}
        </select>
        {errors.property && <span className="lead-err">{errors.property}</span>}
      </div>

      {submitError && (
        <div className="lead-err lead-err-banner" role="alert">
          {submitError}
        </div>
      )}

      <button type="submit" className="btn btn-green lead-submit" disabled={submitting}>
        {submitting ? "Sending…" : "Get a Free Site Visit"} {submitting ? null : <Arrow />}
      </button>
    </form>
  );
}

