"use client";

import { FormEvent, useEffect, useRef, useState } from "react";
import { services } from "@/lib/site";
import { business } from "@/lib/business";
import { Arrow, PhoneIcon } from "@/components/Icons";
import {
  allowEmailKey,
  allowNameKey,
  allowPhoneKey,
  sanitizeEmail,
  sanitizeName,
  sanitizePhone,
  validateName,
  validateOptionalEmail,
  validatePhone,
  validateRequiredSelect,
} from "@/lib/formValidation";
import { submitLead } from "@/lib/leads/submitLead";

const STORAGE_KEY = "hind-lead-popup-seen-v2";
const POPUP_DELAY_MS = 30_000;

function validate(name: string, phone: string, email: string, service: string) {
  const errors: Record<string, string> = {};
  const nameErr = validateName(name);
  const phoneErr = validatePhone(phone);
  const emailErr = validateOptionalEmail(email);
  const serviceErr = validateRequiredSelect(service, "service");
  if (nameErr) errors.name = nameErr;
  if (phoneErr) errors.phone = phoneErr;
  if (emailErr) errors.email = emailErr;
  if (serviceErr) errors.service = serviceErr;
  return errors;
}

export function LeadPopup() {
  const [open, setOpen] = useState(false);
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [service, setService] = useState("");
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [sent, setSent] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState("");
  const [honeypot, setHoneypot] = useState("");
  const firstField = useRef<HTMLInputElement>(null);

  useEffect(() => {
    try {
      if (localStorage.getItem(STORAGE_KEY) === "1") return;
    } catch {
      /* ignore */
    }
    const timer = window.setTimeout(() => setOpen(true), POPUP_DELAY_MS);
    return () => window.clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!open) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    firstField.current?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") dismiss();
    };
    window.addEventListener("keydown", onKey);
    return () => {
      document.body.style.overflow = prev;
      window.removeEventListener("keydown", onKey);
    };
  }, [open]);

  function markSeen() {
    try {
      localStorage.setItem(STORAGE_KEY, "1");
    } catch {
      /* ignore */
    }
  }

  function dismiss() {
    setOpen(false);
  }

  async function submit(e: FormEvent) {
    e.preventDefault();
    if (honeypot) {
      markSeen();
      setSent(true);
      return;
    }
    const next = validate(name, phone, email, service);
    setErrors(next);
    if (Object.keys(next).length) return;

    setSubmitting(true);
    setSubmitError("");
    const result = await submitLead({
      source: "homepage-popup",
      name,
      phone,
      email: email.trim() || undefined,
      service,
      honeypot,
    });
    setSubmitting(false);
    if (!result.ok) {
      setSubmitError(result.error);
      return;
    }
    markSeen();
    setSent(true);
  }

  if (!open) return null;

  return (
    <div className="lead-pop-backdrop" onClick={dismiss} role="presentation">
      <div
        className="lead-pop"
        role="dialog"
        aria-modal="true"
        aria-labelledby="lead-pop-title"
        onClick={(e) => e.stopPropagation()}
      >
        <button type="button" className="lead-pop-close" onClick={dismiss} aria-label="Close">
          ×
        </button>

        <div className="lead-pop-head">
          <span className="lead-pop-mark" aria-hidden>
            <img src="/images/favicon-32.png" alt="" width={28} height={28} />
          </span>
          <p className="lead-pop-kicker">Free site visit</p>
          <h2 id="lead-pop-title">Tell us what you need</h2>
          <p>
            Three details. The studio calls you back — no spam.
          </p>
          <div className="lead-pop-pills">
            <span>Free site visit</span>
            <span>Named plant list</span>
            <span>Reply in hours</span>
          </div>
        </div>

        {sent ? (
          <div className="lead-pop-done" role="status">
            <strong>Got it, {name.trim().split(" ")[0] || "there"}.</strong>
            <p>
              We&apos;ll call <b>{phone}</b> about <b>{service}</b> within a few hours.
              {email.trim() ? " A confirmation email has been sent to you." : ""}
            </p>
            <button type="button" className="btn btn-green" onClick={dismiss}>
              Continue browsing <Arrow />
            </button>
          </div>
        ) : (
          <form className="lead-pop-form" onSubmit={submit} noValidate>
            <label className="sr-only" aria-hidden>
              Company website
              <input tabIndex={-1} autoComplete="off" value={honeypot} onChange={(e) => setHoneypot(e.target.value)} />
            </label>

            <label className={errors.name ? "has-error" : undefined}>
              Name
              <input
                ref={firstField}
                name="name"
                autoComplete="name"
                placeholder="Your full name"
                value={name}
                maxLength={60}
                inputMode="text"
                onKeyDown={allowNameKey}
                onChange={(e) => {
                  setName(sanitizeName(e.target.value));
                  setErrors((p) => ({ ...p, name: "" }));
                }}
              />
              {errors.name && <span className="field-error">{errors.name}</span>}
            </label>

            <label className={errors.phone ? "has-error" : undefined}>
              Phone number
              <input
                name="phone"
                type="tel"
                inputMode="numeric"
                pattern="[6-9][0-9]{9}"
                maxLength={10}
                autoComplete="tel"
                placeholder="10-digit mobile"
                value={phone}
                onKeyDown={allowPhoneKey}
                onChange={(e) => {
                  setPhone(sanitizePhone(e.target.value));
                  setErrors((p) => ({ ...p, phone: "" }));
                }}
              />
              {errors.phone && <span className="field-error">{errors.phone}</span>}
            </label>

            <label className={errors.email ? "has-error" : undefined}>
              Email <span className="cm-opt">(optional)</span>
              <input
                name="email"
                type="email"
                inputMode="email"
                autoComplete="email"
                maxLength={80}
                placeholder="you@email.com"
                value={email}
                onKeyDown={allowEmailKey}
                onChange={(e) => {
                  setEmail(sanitizeEmail(e.target.value));
                  setErrors((p) => ({ ...p, email: "" }));
                }}
              />
              {errors.email && <span className="field-error">{errors.email}</span>}
            </label>

            <label className={errors.service ? "has-error" : undefined}>
              Service
              <select
                name="service"
                value={service}
                onChange={(e) => {
                  setService(e.target.value);
                  setErrors((p) => ({ ...p, service: "" }));
                }}
              >
                <option value="">Choose a service…</option>
                {services.map((s) => (
                  <option key={s.slug} value={s.title}>
                    {s.title}
                  </option>
                ))}
              </select>
              {errors.service && <span className="field-error">{errors.service}</span>}
            </label>

            {submitError && (
              <div className="field-error lead-pop-submit-error" role="alert">
                {submitError}
              </div>
            )}

            <button type="submit" className="btn btn-green lead-pop-submit" disabled={submitting}>
              {submitting ? "Sending…" : "Request a callback"} {submitting ? null : <Arrow />}
            </button>
            <a href={`tel:${business.phoneTel}`} className="lead-pop-call">
              <PhoneIcon size={15} /> Prefer to call? {business.phone}
            </a>
            <button type="button" className="lead-pop-skip" onClick={dismiss}>
              Skip for now
            </button>
          </form>
        )}
      </div>
    </div>
  );
}

"use client";

import { FormEvent, useMemo, useState } from "react";
import { services } from "@/lib/site";
import { Arrow } from "@/components/Icons";
import {
  allowEmailKey,
  allowNameKey,
  allowPhoneKey,
  sanitizeEmail,
  sanitizeMessage,
  sanitizeName,
  sanitizePhone,
  validateEmail,
  validateName,
  validateOptionalMessage,
  validatePhone,
  validateRequiredSelect,
} from "@/lib/formValidation";
import { submitLead } from "@/lib/leads/submitLead";

type FieldErrors = Partial<Record<"name" | "phone" | "email" | "service" | "message", string>>;

function validate(values: {
  name: string;
  phone: string;
  email: string;
  service: string;
  message: string;
}): FieldErrors {
  const errors: FieldErrors = {};
  const nameErr = validateName(values.name);
  const phoneErr = validatePhone(values.phone);
  const emailErr = validateEmail(values.email);
  const serviceErr = validateRequiredSelect(values.service, "service");
  const messageErr = validateOptionalMessage(values.message);
  if (nameErr) errors.name = nameErr;
  if (phoneErr) errors.phone = phoneErr;
  if (emailErr) errors.email = emailErr;
  if (serviceErr) errors.service = serviceErr;
  if (messageErr) errors.message = messageErr;
  return errors;
}

export function QuoteForm() {
  const [values, setValues] = useState({
    name: "",
    phone: "",
    email: "",
    service: "",
    message: "",
  });
  const [errors, setErrors] = useState<FieldErrors>({});
  const [touched, setTouched] = useState<Record<string, boolean>>({});
  const [sent, setSent] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState("");
  const [honeypot, setHoneypot] = useState("");

  const hasErrors = useMemo(() => Object.keys(errors).length > 0, [errors]);

  function update<K extends keyof typeof values>(key: K, value: string) {
    setValues((prev) => {
      const next = { ...prev, [key]: value };
      if (touched[key]) setErrors(validate(next));
      return next;
    });
  }

  function onBlur(key: keyof typeof values) {
    setTouched((prev) => ({ ...prev, [key]: true }));
    setValues((prev) => {
      setErrors(validate(prev));
      return prev;
    });
  }

  async function onSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (honeypot) {
      setSent(true);
      return;
    }

    const nextErrors = validate(values);
    setTouched({ name: true, phone: true, email: true, service: true, message: true });
    setErrors(nextErrors);
    if (Object.keys(nextErrors).length > 0) return;

    setSubmitting(true);
    setSubmitError("");
    const result = await submitLead({
      source: "quote-form",
      name: values.name,
      phone: values.phone,
      email: values.email,
      service: values.service,
      message: values.message,
      honeypot,
    });
    setSubmitting(false);
    if (!result.ok) {
      setSubmitError(result.error);
      return;
    }
    setSent(true);
  }

  if (sent) {
    return (
      <div className="form form-success" role="status" aria-live="polite">
        <h3>Thank you — request received</h3>
        <p>
          Thank you for choosing Hind Landscape Co. We&apos;ve saved your details for{" "}
          <strong>{values.name}</strong>. Our team will contact you on{" "}
          <strong>{values.phone}</strong> or <strong>{values.email}</strong>.
          A confirmation email has been sent to you.
        </p>
        <button
          type="button"
          className="btn btn-outline"
          onClick={() => {
            setSent(false);
            setValues({
              name: "",
              phone: "",
              email: "",
              service: "",
              message: "",
            });
            setErrors({});
            setTouched({});
          }}
        >
          Send another request
        </button>
      </div>
    );
  }

  return (
    <form className="form" onSubmit={onSubmit} noValidate>
      <label className={touched.name && errors.name ? "has-error" : undefined}>
        Full name
        <input
          name="name"
          autoComplete="name"
          value={values.name}
          maxLength={60}
          inputMode="text"
          onKeyDown={allowNameKey}
          onChange={(e) => update("name", sanitizeName(e.target.value))}
          onBlur={() => onBlur("name")}
          placeholder="Your name"
          aria-invalid={Boolean(touched.name && errors.name)}
          aria-describedby={errors.name ? "err-name" : undefined}
        />
        {touched.name && errors.name && (
          <span className="field-error" id="err-name">
            {errors.name}
          </span>
        )}
      </label>

      <label className={touched.phone && errors.phone ? "has-error" : undefined}>
        Phone
        <input
          name="phone"
          type="tel"
          inputMode="numeric"
          pattern="[6-9][0-9]{9}"
          maxLength={10}
          autoComplete="tel"
          value={values.phone}
          onKeyDown={allowPhoneKey}
          onChange={(e) => update("phone", sanitizePhone(e.target.value))}
          onBlur={() => onBlur("phone")}
          placeholder="10-digit mobile number"
          aria-invalid={Boolean(touched.phone && errors.phone)}
          aria-describedby={errors.phone ? "err-phone" : undefined}
        />
        {touched.phone && errors.phone && (
          <span className="field-error" id="err-phone">
            {errors.phone}
          </span>
        )}
      </label>

      <label className={touched.email && errors.email ? "has-error" : undefined}>
        Email
        <input
          type="email"
          name="email"
          autoComplete="email"
          inputMode="email"
          maxLength={80}
          value={values.email}
          onKeyDown={allowEmailKey}
          onChange={(e) => update("email", sanitizeEmail(e.target.value))}
          onBlur={() => onBlur("email")}
          placeholder="you@email.com"
          aria-invalid={Boolean(touched.email && errors.email)}
          aria-describedby={errors.email ? "err-email" : undefined}
        />
        {touched.email && errors.email && (
          <span className="field-error" id="err-email">
            {errors.email}
          </span>
        )}
      </label>

      <label className={touched.service && errors.service ? "has-error" : undefined}>
        Service
        <select
          name="service"
          value={values.service}
          onChange={(e) => update("service", e.target.value)}
          onBlur={() => onBlur("service")}
          aria-invalid={Boolean(touched.service && errors.service)}
        >
          <option value="">Choose a service…</option>
          {services.map((s) => (
            <option key={s.slug} value={s.title}>
              {s.title}
            </option>
          ))}
          <option value="Not sure yet">Not sure yet</option>
        </select>
        {touched.service && errors.service && <span className="field-error">{errors.service}</span>}
      </label>

      <label className={touched.message && errors.message ? "has-error" : undefined}>
        Tell us about the space <em>(optional)</em>
        <textarea
          name="message"
          value={values.message}
          maxLength={800}
          onChange={(e) => update("message", sanitizeMessage(e.target.value))}
          onBlur={() => onBlur("message")}
          placeholder="Lawn, patio, lighting, a full garden…"
          rows={4}
          aria-invalid={Boolean(touched.message && errors.message)}
          aria-describedby={errors.message ? "err-message" : undefined}
        />
        {touched.message && errors.message && (
          <span className="field-error" id="err-message">
            {errors.message}
          </span>
        )}
      </label>

      {hasErrors && Object.values(touched).some(Boolean) && (
        <div className="form-banner" role="alert">
          Please fix the highlighted fields before submitting.
        </div>
      )}

      <label style={{ position: "absolute", left: "-9999px", top: "auto", width: 1, height: 1, overflow: "hidden" }} aria-hidden="true">
        <span>Do not fill this field</span>
        <input
          type="text"
          name="website_url"
          tabIndex={-1}
          autoComplete="off"
          value={honeypot}
          onChange={(e) => setHoneypot(e.target.value)}
        />
      </label>

      {submitError && (
        <div className="form-banner" role="alert">
          {submitError}
        </div>
      )}

      <button className="btn btn-green" type="submit" disabled={submitting}>
        {submitting ? "Sending…" : "Get a Free Quote"} {submitting ? null : <Arrow />}
      </button>
    </form>
  );
}
